import{_ as a,o as r,c as t,a3 as n}from"./chunks/framework.DQ-7HQaQ.js";const u=JSON.parse('{"title":"Concept reading guide","description":"Primary explanations of retrieval, document knowledge, workflows, and streaming UI concepts.","frontmatter":{"title":"Concept reading guide","description":"Primary explanations of retrieval, document knowledge, workflows, and streaming UI concepts."},"headers":[],"relativePath":"research/concepts.md","filePath":"research/concepts.md","lastUpdated":1794376220000}'),i={name:"research/concepts.md"};function o(s,e,d,c,l,h){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="concept-reading-guide" tabindex="-1">Concept reading guide <a class="header-anchor" href="#concept-reading-guide" aria-label="Permalink to &quot;Concept reading guide&quot;">​</a></h1><p><strong>Sources checked: November 5, 2026.</strong> Use this guide to connect the vocabulary in the draft architecture to primary explanations. The links teach mechanisms; they do not establish that a particular product is our final choice. Each annotation identifies why the concept matters and where it appears in our design.</p><h2 id="suggested-reading-order" tabindex="-1">Suggested reading order <a class="header-anchor" href="#suggested-reading-order" aria-label="Permalink to &quot;Suggested reading order&quot;">​</a></h2><ol><li>Start with <strong>BM25, vectors, and rank fusion</strong> to understand how passages become answer candidates.</li><li>Read <strong>chunking, NER, linking, and graph search</strong> to see how documents become structured evidence.</li><li>Study <strong>dependencies, retries, messaging, and WAL</strong> before deciding how ingestion runs and publishes updates.</li><li>Finish with <strong>reactivity, SSE, and recovery</strong>, then trace one document upload and one interrupted answer through the <a href="/knowledge-lab/architecture/overview">system overview</a>.</li></ol><h2 id="retrieval-foundations" tabindex="-1">Retrieval foundations <a class="header-anchor" href="#retrieval-foundations" aria-label="Permalink to &quot;Retrieval foundations&quot;">​</a></h2><h3 id="bm25-and-full-text-search" tabindex="-1">BM25 and full-text search <a class="header-anchor" href="#bm25-and-full-text-search" aria-label="Permalink to &quot;BM25 and full-text search&quot;">​</a></h3><p><strong>Learn here:</strong> <a href="https://sqlite.org/fts5.html#the_bm25_function" target="_blank" rel="noreferrer">SQLite FTS5 and its BM25 function</a>. It explains lexical matching and relevance ranking; FTS5 assigns better matches lower scores. Our keyword branch needs this behavior for useful literal matches and correct result ordering. <strong>Related:</strong> <a href="/knowledge-lab/architecture/retrieval#three-complementary-signals">Three retrieval signals</a>.</p><h3 id="exact-and-approximate-vector-search" tabindex="-1">Exact and approximate vector search <a class="header-anchor" href="#exact-and-approximate-vector-search" aria-label="Permalink to &quot;Exact and approximate vector search&quot;">​</a></h3><p><strong>Learn here:</strong> <a href="https://sqlite.org/vec1doc.html" target="_blank" rel="noreferrer">SQLite Vec1 user manual</a>. Compare exhaustive nearest-neighbor search with trained approximate indexes, filtering, and reranking. Our vector selection must measure eligible-result recall alongside latency rather than assume all semantic indexes behave alike. <strong>Related:</strong> <a href="/knowledge-lab/architecture/retrieval#vector-capability-decision">Vector capability decision</a>.</p><h3 id="reciprocal-rank-fusion" tabindex="-1">Reciprocal rank fusion <a class="header-anchor" href="#reciprocal-rank-fusion" aria-label="Permalink to &quot;Reciprocal rank fusion&quot;">​</a></h3><p><strong>Learn here:</strong> <a href="https://www.elastic.co/docs/reference/elasticsearch/rest-apis/reciprocal-rank-fusion" target="_blank" rel="noreferrer">Elastic&#39;s RRF explanation and formula</a>. RRF combines positions in ranked lists rather than requiring identical score scales. Our initial hybrid baseline can therefore combine keyword and semantic candidates without adding incompatible raw scores. <strong>Related:</strong> <a href="/knowledge-lab/architecture/retrieval#candidate-composition">Candidate composition</a>.</p><h2 id="documents-and-extracted-knowledge" tabindex="-1">Documents and extracted knowledge <a class="header-anchor" href="#documents-and-extracted-knowledge" aria-label="Permalink to &quot;Documents and extracted knowledge&quot;">​</a></h2><h3 id="structure-aware-chunking" tabindex="-1">Structure-aware chunking <a class="header-anchor" href="#structure-aware-chunking" aria-label="Permalink to &quot;Structure-aware chunking&quot;">​</a></h3><p><strong>Learn here:</strong> <a href="https://docling-project.github.io/docling/concepts/chunking/" target="_blank" rel="noreferrer">Docling chunking concepts</a>. Study document structure, token budgets, and contextualized chunk representations. Our pipeline needs retrieval-sized passages while preserving parent sections and source locations for extraction and citations. <strong>Related:</strong> <a href="/knowledge-lab/architecture/ingestion#parsing-and-chunking">Parsing and chunking</a>.</p><h3 id="named-entity-recognition" tabindex="-1">Named entity recognition <a class="header-anchor" href="#named-entity-recognition" aria-label="Permalink to &quot;Named entity recognition&quot;">​</a></h3><p><strong>Learn here:</strong> <a href="https://spacy.io/usage/linguistic-features#named-entities" target="_blank" rel="noreferrer">spaCy&#39;s named-entity guide</a>. NER identifies spans and categories in text. Our mention records must preserve those spans separately from canonical identities; detecting a name alone does not resolve which entity it denotes. <strong>Related:</strong> <a href="/knowledge-lab/architecture/ingestion#nlp-and-entity-extraction">NLP and entity extraction</a>.</p><h3 id="entity-linking-and-disambiguation" tabindex="-1">Entity linking and disambiguation <a class="header-anchor" href="#entity-linking-and-disambiguation" aria-label="Permalink to &quot;Entity linking and disambiguation&quot;">​</a></h3><p><strong>Learn here:</strong> <a href="https://spacy.io/api/entitylinker" target="_blank" rel="noreferrer">spaCy EntityLinker</a>. It describes knowledge-base candidates and contextual selection. Our resolver needs stable identifiers, supporting context, and an unresolved outcome so ambiguous names do not force destructive merges. <strong>Related:</strong> <a href="/knowledge-lab/architecture/retrieval#evidence-model">Evidence model</a>.</p><h3 id="local-and-global-graph-retrieval" tabindex="-1">Local and global graph retrieval <a class="header-anchor" href="#local-and-global-graph-retrieval" aria-label="Permalink to &quot;Local and global graph retrieval&quot;">​</a></h3><p><strong>Learn here:</strong> GraphRAG&#39;s <a href="https://microsoft.github.io/graphrag/query/local_search/" target="_blank" rel="noreferrer">local search</a> and <a href="https://microsoft.github.io/graphrag/query/global_search/" target="_blank" rel="noreferrer">global search</a>. Compare entity-focused evidence with corpus-level community summaries. Our design should evaluate these question types separately and keep generated summaries linked to their underlying sources. <strong>Related:</strong> <a href="/knowledge-lab/architecture/ingestion#claims-and-augmentation">Claims and augmentation</a>.</p><h2 id="workflow-and-storage-behavior" tabindex="-1">Workflow and storage behavior <a class="header-anchor" href="#workflow-and-storage-behavior" aria-label="Permalink to &quot;Workflow and storage behavior&quot;">​</a></h2><h3 id="assets-and-dependency-graphs" tabindex="-1">Assets and dependency graphs <a class="header-anchor" href="#assets-and-dependency-graphs" aria-label="Permalink to &quot;Assets and dependency graphs&quot;">​</a></h3><p><strong>Learn here:</strong> <a href="https://dagster.io/docs/guides/build/assets" target="_blank" rel="noreferrer">Dagster assets</a>. An asset describes a persistent result and how it depends on other results. This helps model our chunks, embeddings, and claims as versioned outputs with explicit recomputation dependencies. <strong>Related:</strong> <a href="/knowledge-lab/architecture/ingestion#artifact-dependencies">Artifact dependencies</a>.</p><h3 id="retries-and-durable-work" tabindex="-1">Retries and durable work <a class="header-anchor" href="#retries-and-durable-work" aria-label="Permalink to &quot;Retries and durable work&quot;">​</a></h3><p><strong>Learn here:</strong> <a href="https://docs.temporal.io/encyclopedia/retry-policies" target="_blank" rel="noreferrer">Temporal retry policies</a>. Read the distinction between workflow logic and failure-prone activities. Our ingestion stages need bounded retry policies and idempotent publication even when execution infrastructure can recover progress. <strong>Related:</strong> <a href="/knowledge-lab/architecture/ingestion#durable-execution-contract">Durable execution contract</a>.</p><h3 id="ephemeral-messaging-and-retained-streams" tabindex="-1">Ephemeral messaging and retained streams <a class="header-anchor" href="#ephemeral-messaging-and-retained-streams" aria-label="Permalink to &quot;Ephemeral messaging and retained streams&quot;">​</a></h3><p><strong>Learn here:</strong> <a href="https://docs.nats.io/concepts/jetstream" target="_blank" rel="noreferrer">NATS JetStream concepts</a>. Core messaging and retained, acknowledged streams provide different delivery behavior. Our jobs and replay requirements need deliberate retention and duplicate handling; transient notifications can use lighter delivery. <strong>Related:</strong> <a href="/knowledge-lab/architecture/backend#etl-durability-and-decision-gates">ETL durability</a>.</p><h3 id="sqlite-wal-and-checkpoints" tabindex="-1">SQLite WAL and checkpoints <a class="header-anchor" href="#sqlite-wal-and-checkpoints" aria-label="Permalink to &quot;SQLite WAL and checkpoints&quot;">​</a></h3><p><strong>Learn here:</strong> <a href="https://sqlite.org/wal.html" target="_blank" rel="noreferrer">SQLite write-ahead logging</a>. Readers can overlap a writer, while long read transactions can delay checkpoint progress. Our retrieval transactions should finish before answer streaming, and ingestion must account for the single-writer boundary. <strong>Related:</strong> <a href="/knowledge-lab/architecture/retrieval#sqlite-operating-boundary">SQLite operating boundary</a>.</p><h2 id="frontend-and-streaming-contracts" tabindex="-1">Frontend and streaming contracts <a class="header-anchor" href="#frontend-and-streaming-contracts" aria-label="Permalink to &quot;Frontend and streaming contracts&quot;">​</a></h2><h3 id="granular-reactive-state" tabindex="-1">Granular reactive state <a class="header-anchor" href="#granular-reactive-state" aria-label="Permalink to &quot;Granular reactive state&quot;">​</a></h3><p><strong>Learn here:</strong> <a href="https://svelte.dev/docs/svelte/$state" target="_blank" rel="noreferrer">Svelte&#39;s reactive state</a>. Read how property changes trigger updates. Our active message, composer, and source panel should have independent state ownership so streaming work does not unnecessarily disturb other interactions. <strong>Related:</strong> <a href="/knowledge-lab/architecture/frontend#state-and-component-ownership">Component ownership</a>.</p><h3 id="sse-framing-and-reconnection" tabindex="-1">SSE framing and reconnection <a class="header-anchor" href="#sse-framing-and-reconnection" aria-label="Permalink to &quot;SSE framing and reconnection&quot;">​</a></h3><p><strong>Learn here:</strong> <a href="https://developer.mozilla.org/en-US/docs/Web/API/Server-sent_events/Using_server-sent_events" target="_blank" rel="noreferrer">MDN&#39;s server-sent events guide</a>. Study event fields, blank-line framing, identifiers, and reconnection behavior. Our stream decoder must assemble complete events across network reads and distinguish transport reconnection from answer recovery. <strong>Related:</strong> <a href="/knowledge-lab/architecture/contracts#event-envelope">Event envelope</a>.</p><h3 id="snapshot-and-replay" tabindex="-1">Snapshot and replay <a class="header-anchor" href="#snapshot-and-replay" aria-label="Permalink to &quot;Snapshot and replay&quot;">​</a></h3><p><strong>Learn here:</strong> our proposed <a href="/knowledge-lab/architecture/contracts#ordering-and-recovery-invariants">ordering and recovery invariants</a> and <a href="/knowledge-lab/architecture/frontend#stream-lifecycle">frontend stream lifecycle</a>. This is our application protocol: snapshots carry cursors, retained events support catch-up, and gaps require explicit resynchronization. SSE itself does not provide event retention or restore failed model inference.</p>',36)])])}const p=a(i,[["render",o]]);export{u as __pageData,p as default};
